const groups={},tests=[];let lines=[];const test=(name,run)=>tests.push({name,run});const log=(...args)=>lines.push(args.join(' '));async function runTests(){for(const {name,run}of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}const attempt=fn=>{try{const v=fn();return v===undefined?'ok':v}catch(e){return e.name}};
test('query-eof-blocks',()=>{const e=document.createElement('div');e.innerHTML='<b class="a" data-x="yes"></b>';for(const q of [':is(.a',':where(.a',':not(.a',':is(.a,',':is(.a,[data-x','[data-x','[data-x=yes','[data-x="yes',':lang("en',':is(.a/*unfinished',':not(:is(.a'])log(q,attempt(()=>e.querySelectorAll(q).length))});
test('query-escaped-function-space',()=>{const e=document.createElement('div');e.innerHTML='<b class="a"></b>';for(const q of [':\\69 s(.a,:unknown)',':\\69 s()',':\\77 here(.a,[)',':IS(.a,:unknown)'])log(q,attempt(()=>e.querySelectorAll(q).length))});
test('css-eof-and-bad-blocks',()=>{const e=document.createElement('div');e.innerHTML='<b class="a" data-x="yes"></b>';for(const q of [':is(.a,[)',':is(.a,[class)',':is([class),.a)',':is(.a,[class))',':not([class',':not([class)',':is(.a,)',':is(.a))','[data-x="yes\n', '[data-x="yes\\\n"]', ':is(.a/*end', '.a/*end', '[data-x=yes/*end', ':is([bad=],.a)', ':where([bad=],.a)'])log(JSON.stringify(q),attempt(()=>e.querySelectorAll(q).length))});
test('css-numeric-identifiers',()=>{const e=document.createElement('div');e.innerHTML='<b id="123" class="123 a" x="123"></b>';for(const q of ['#123','.123','123','123abc','[x=123]','#\\31 23','.\\31 23','[x=\\31 23]',':is(#123,.a)',':is(.123,.a)',':not(#123)'])log(q,attempt(()=>e.querySelectorAll(q).length))});
test('css-comments-and-boundaries',()=>{const e=document.createElement('div');e.innerHTML='<b class="a"></b>';for(const q of ['b/**/.a','b/**/b',':/**/is(.a)',':is/**/(.a)',':is(.a/**/,:unknown)','b /*c*/ .a','b/**/> i','.a/**/','/*x*/.a',':\\69\r\ns(.a,:unknown)'])log(JSON.stringify(q),attempt(()=>e.querySelectorAll(q).length))});
test('css-nth-token-values',()=>{const e=document.createElement('div');e.innerHTML='<b class="a"></b><b></b>';for(const q of [':nth-child(1)',':nth-child(1.0)',':nth-child(1.0n)',':nth-child(1e0)',':nth-child(+n)',':nth-child(2n+1)',':nth-child(2n + 1)',':nth-child(1 of .a',':nth-child(1 of :is(.a,:unknown)',':nth-child(2n/**/+1)'])log(q,attempt(()=>e.querySelectorAll(q).length))});
