test('css-comment-token-joins',()=>{const e=document.createElement('div');e.innerHTML='<b class="a" x="yes"></b><b></b>';for(const q of ['#/**/id','[x~/**/=yes]','[x=y/**/es]',':nth-child(2/**/n)',':nth-child(2n/**/+1)',':nth-child(n/**/-1)',':nth-child(+/**/n)',':nth-child(n-/**/1)',':nth-child(1/**/of/**/.a)',':nth-child(1 of.a)',':nth-child(1 of b/**/b)','[x="yes"/**/i]',':/**/is(.a)','b/**/b',':is(b/**/b,.a)'])log(q,attempt(()=>e.querySelectorAll(q).length))});
test('css-attribute-value-grammar',()=>{const e=document.createElement('b');e.setAttribute('x','foo:bar');for(const q of ['[x=foo:bar]','[x=foo/bar]','[x=#abc]','[x=foo()]','[x=:is()]','[x=*]','[x=]','[x=foo bar]','[x="foo:bar"]','[x=foo\\:bar]','[x=foo/**/bar]','[x="foo:bar"i]','[*|x]','[|x]','[x s]'])log(q,attempt(()=>e.matches(q)))});
